import fs from "fs";
import path from "path";
import { describe, expect, it } from "vitest";
import { generateMap } from "../src/core/game/MapGenerator";
import { decodePng } from "./util/Png";

const ROOT = path.join(__dirname, "..");

// The official maps, generated by the Go tool (map-generator/): the port
// must give the very same files from the same images. One map per kind of
// image: RGB, RGBA with transparency, an 8-bit palette, a 1-bit palette.
// Madagascar was generated upstream and copied as is: the port must agree.
const MAPS = ["beringstrait", "tourney1", "thebox", "sierpinski", "madagascar"];

describe("map generator", () => {
  for (const name of MAPS) {
    it(`makes ${name} byte for byte like the official generator`, () => {
      const image = decodePng(
        path.join(ROOT, "map-generator/assets/maps", name, "image.png"),
      );
      const out = generateMap(image);
      const dir = path.join(ROOT, "resources/maps", name);
      const manifest = JSON.parse(
        fs.readFileSync(path.join(dir, "manifest.json"), "utf8"),
      );
      for (const [scale, file, key] of [
        [out.map, "map.bin", "map"],
        [out.map4x, "map4x.bin", "map4x"],
        [out.map16x, "map16x.bin", "map16x"],
      ] as const) {
        expect(scale.width).toBe(manifest[key].width);
        expect(scale.height).toBe(manifest[key].height);
        expect(scale.numLandTiles).toBe(manifest[key].num_land_tiles);
        const expected = new Uint8Array(fs.readFileSync(path.join(dir, file)));
        expect(scale.data.length).toBe(expected.length);
        // Compared as a whole, without dumping millions of bytes on failure.
        const firstDiff = scale.data.findIndex((b, i) => b !== expected[i]);
        expect(firstDiff).toBe(-1);
      }
    }, 60_000);
  }

  it("turns blue into terrain and refuses an image without land", () => {
    const px = (r: number, g: number, b: number, a = 255) => [r, g, b, a];
    // 8x4: water on the left half, plains and mountains on the right.
    const rgba: number[] = [];
    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 8; x++) {
        rgba.push(
          ...(x < 4 ? px(0, 0, 106) : x < 6 ? px(10, 10, 140) : px(0, 0, 200)),
        );
      }
    }
    const out = generateMap(
      { width: 8, height: 4, rgba: new Uint8Array(rgba) },
      false,
    );
    expect(out.map.numLandTiles).toBe(16);
    // Shoreline land, magnitude 0 at x=4; mountain (30) at x=7.
    expect(out.map.data[4]).toBe(0b11000000);
    expect(out.map.data[7] & 0b11111).toBe(30);
    expect(out.map.data[7] & 0b10000000).toBe(0b10000000);

    const water = new Uint8Array(8 * 4 * 4);
    for (let i = 0; i < water.length; i += 4) water[i + 2] = 106;
    expect(() => generateMap({ width: 8, height: 4, rgba: water })).toThrow(
      "0 land tiles",
    );
  });
});
